describe('Error Messages Screen Reader Accessibility', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should have proper ARIA attributes on error messages for screen reader accessibility', () => {
    // Trigger an error state by submitting an empty form
    cy.get('form').within(() => {
      cy.get('input[name="email"]').should('exist');
      cy.get('button[type="submit"]').click();
    });

    // Verify error message has proper ARIA attributes
    cy.get('[role="alert"]').should('exist');
    cy.get('[role="alert"]').should('have.attr', 'aria-live', 'polite');
    cy.get('[role="alert"]').should('have.attr', 'aria-atomic', 'true');

    // Verify error message text is present and accessible
    cy.get('[role="alert"]').should('contain.text', 'Email is required');
    cy.get('[role="alert"]').should('be.visible');

    // Verify error message is associated with form field
    cy.get('input[name="email"]').should('have.attr', 'aria-describedby');
    const errorId = cy.get('input[name="email"]').invoke('attr', 'aria-describedby');
    cy.get(`#${errorId}`).should('exist');
  });

  it('should announce multiple error messages to screen readers in correct order', () => {
    // Submit form with multiple validation errors
    cy.get('form').within(() => {
      cy.get('input[name="email"]').clear();
      cy.get('input[name="password"]').clear();
      cy.get('button[type="submit"]').click();
    });

    // Verify error container has alert role
    cy.get('[role="alert"]').should('have.length.greaterThan', 0);

    // Verify each error message has proper ARIA attributes
    cy.get('[role="alert"]').each(($alert) => {
      cy.wrap($alert).should('have.attr', 'aria-live');
      cy.wrap($alert).should('have.attr', 'aria-atomic', 'true');
      cy.wrap($alert).should('not.be.empty');
    });

    // Verify error messages are not hidden from screen readers
    cy.get('[role="alert"]').each(($alert) => {
      cy.wrap($alert).should('not.have.attr', 'aria-hidden', 'true');
    });
  });

  it('should clear error messages and update ARIA attributes when user corrects input', () => {
    // Trigger error state
    cy.get('form').within(() => {
      cy.get('button[type="submit"]').click();
    });

    // Verify error is present
    cy.get('[role="alert"]').should('exist');
    cy.get('[role="alert"]').should('contain.text', 'Email is required');

    // User corrects the input
    cy.get('input[name="email"]').type('test@example.com');
    cy.get('form').within(() => {
      cy.get('button[type="submit"]').click();
    });

    // Verify error message is removed or updated
    cy.get('[role="alert"]').should('not.exist');

    // Verify input field no longer has error aria-describedby
    cy.get('input[name="email"]').should('not.have.attr', 'aria-describedby');
  });

  it('should have descriptive error messages that are meaningful to screen reader users', () => {
    // Trigger validation error with specific message
    cy.get('input[name="email"]').focus();
    cy.get('input[name="email"]').blur();

    // Wait for error to appear
    cy.get('[role="alert"]').should('exist');

    // Verify error message is descriptive and not generic
    cy.get('[role="alert"]').invoke('text').then((text) => {
      expect(text).to.not.be.empty;
      expect(text.length).to.be.greaterThan(5);
      expect(text).to.match(/email|required|invalid/i);
    });

    // Verify error message includes field context
    cy.get('input[name="email"]').parent().within(() => {
      cy.get('[role="alert"]').should('exist');
    });
  });
});
